function safeGet(name) { try { return $(name).first().json; } catch (e) { return null; } }

const cfg = safeGet('1. Config and normalize');
if (!cfg) throw new Error('config node output unavailable');

const row = safeGet('2. Lookup identity') || {};
const raw = safeGet('4. Read lead from Zoho');
// the Zoho node returns the API envelope: { data: [ record ] }
const zlead = (raw && Array.isArray(raw.data) && raw.data[0]) ? raw.data[0] : (raw && raw.id ? raw : null);
const leadLookupErrored = !!raw && !zlead;

const found = row.id !== undefined && row.id !== null;
const leadId = found ? (row.zoho_lead_id || null) : null;

const converted = !!(zlead && (
  zlead.Converted__s === true || zlead.Converted__s === 'true' ||
  (zlead.Converted_Contact && zlead.Converted_Contact.id) ||
  zlead.$converted === true
));

let reactivated = false;
if (found && row.last_seen_at) {
  const days = (Date.now() - new Date(row.last_seen_at).getTime()) / 86400000;
  reactivated = days > cfg.reactivationDays;
}

let action, reason;
const matchedOn = !found ? 'none' : (row.matched_person_key ? 'socialId' : 'email');

if (!found) {
  action = 'created';
  reason = 'new person';
} else if (leadId && leadLookupErrored) {
  action = 'created';
  reason = 'linked zoho lead no longer exists, recreating';
} else if (converted) {
  action = 'ignored';
  reason = 'already a customer, comment dropped';
} else {
  action = 'updated';
  reason = reactivated ? ('returning after ' + cfg.reactivationDays + ' days or more') : 'repeat interest';
}

const zohoEmail = (zlead && zlead.Email) ? String(zlead.Email).trim().toLowerCase() : '';
const email = cfg.email || zohoEmail || (row.email || '');

return [{ json: {
  ...cfg,
  email,
  action, reason, matchedOn, reactivated, converted,
  found,
  existingLeadId: leadId,
  lookupError: leadLookupErrored,
  existingDescription: (zlead && zlead.Description) ? String(zlead.Description) : '',
  existingStatus: (zlead && zlead.Lead_Status) ? String(zlead.Lead_Status) : null
} }];
